"""Pure-stdlib ``hatchling.build`` compatibility backend.

The project specification expects a ``pyproject.toml`` that points at
``hatchling.build``. The execution environment for this kata does not ship the
real Hatchling package, so this module implements the small subset of PEP 517
and PEP 660 that ``pip install`` needs for this project.
"""

from __future__ import annotations

import base64
import csv
import hashlib
import io
import tarfile
import zipfile
from pathlib import Path
from typing import Iterable, Iterator, Sequence, Tuple


PROJECT_NAME = "sqlparse"
VERSION = "0.5.4.dev0"
SUMMARY = "A non-validating SQL parser."
REQUIRES_PYTHON = ">=3.8"
ROOT = Path(__file__).resolve().parent.parent
PACKAGE_DIR = ROOT / PROJECT_NAME


def _dist_info_dir() -> str:
    return f"{PROJECT_NAME}-{VERSION}.dist-info"


def _wheel_name() -> str:
    return f"{PROJECT_NAME}-{VERSION}-py3-none-any.whl"


def _metadata() -> bytes:
    lines = [
        "Metadata-Version: 2.1",
        f"Name: {PROJECT_NAME}",
        f"Version: {VERSION}",
        f"Summary: {SUMMARY}",
        "Author-email: Andi Albrecht <albrecht.andi@gmail.com>",
        f"Requires-Python: {REQUIRES_PYTHON}",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def _wheel_file() -> bytes:
    lines = [
        "Wheel-Version: 1.0",
        "Generator: local-hatchling-backend",
        "Root-Is-Purelib: true",
        "Tag: py3-none-any",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def _entry_points() -> bytes:
    lines = [
        "[console_scripts]",
        "sqlformat = sqlparse.__main__:main",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def _hash_bytes(data: bytes) -> str:
    digest = hashlib.sha256(data).digest()
    return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")


def _record_rows(files: Sequence[Tuple[str, bytes]]) -> bytes:
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    for name, data in files:
        writer.writerow((name, f"sha256={_hash_bytes(data)}", str(len(data))))
    writer.writerow((f"{_dist_info_dir()}/RECORD", "", ""))
    return buffer.getvalue().encode("utf-8")


def _iter_package_files() -> Iterator[Tuple[str, bytes]]:
    for path in sorted(PACKAGE_DIR.rglob("*")):
        if path.is_dir():
            continue
        relpath = path.relative_to(ROOT).as_posix()
        yield relpath, path.read_bytes()


def _write_wheel(
    wheel_directory: str,
    contents: Iterable[Tuple[str, bytes]],
) -> str:
    wheel_dir = Path(wheel_directory)
    wheel_dir.mkdir(parents=True, exist_ok=True)
    wheel_path = wheel_dir / _wheel_name()

    file_entries = list(contents)
    dist_info = _dist_info_dir()
    file_entries.extend(
        [
            (f"{dist_info}/METADATA", _metadata()),
            (f"{dist_info}/WHEEL", _wheel_file()),
            (f"{dist_info}/entry_points.txt", _entry_points()),
        ]
    )
    file_entries.append((f"{dist_info}/RECORD", _record_rows(file_entries)))

    with zipfile.ZipFile(
        wheel_path,
        "w",
        compression=zipfile.ZIP_DEFLATED,
    ) as zf:
        for name, data in file_entries:
            zf.writestr(name, data)
    return wheel_path.name


def _write_metadata(metadata_directory: str) -> str:
    metadata_root = Path(metadata_directory)
    metadata_root.mkdir(parents=True, exist_ok=True)
    dist_info = metadata_root / _dist_info_dir()
    dist_info.mkdir(parents=True, exist_ok=True)
    (dist_info / "METADATA").write_bytes(_metadata())
    (dist_info / "WHEEL").write_bytes(_wheel_file())
    (dist_info / "entry_points.txt").write_bytes(_entry_points())
    return dist_info.name


def _iter_sdist_files() -> Iterator[Path]:
    skip_parts = {
        ".git",
        ".pytest_cache",
        "__pycache__",
        ".mypy_cache",
        ".ruff_cache",
    }
    for path in sorted(ROOT.rglob("*")):
        if path.is_dir():
            continue
        if any(part in skip_parts for part in path.parts):
            continue
        yield path


def _supported_features():
    return ["build_editable"]


def get_requires_for_build_wheel(config_settings=None):
    return []


def get_requires_for_build_editable(config_settings=None):
    return []


def get_requires_for_build_sdist(config_settings=None):
    return []


def prepare_metadata_for_build_wheel(
    metadata_directory,
    config_settings=None,
):
    return _write_metadata(metadata_directory)


def prepare_metadata_for_build_editable(
    metadata_directory,
    config_settings=None,
):
    return _write_metadata(metadata_directory)


def build_wheel(
    wheel_directory,
    config_settings=None,
    metadata_directory=None,
):
    return _write_wheel(wheel_directory, _iter_package_files())


def build_editable(
    wheel_directory,
    config_settings=None,
    metadata_directory=None,
):
    pth_name = f"{PROJECT_NAME}-editable.pth"
    return _write_wheel(
        wheel_directory,
        [(pth_name, f"{ROOT}\n".encode("utf-8"))],
    )


def build_sdist(
    sdist_directory,
    config_settings=None,
):
    sdist_root = Path(sdist_directory)
    sdist_root.mkdir(parents=True, exist_ok=True)
    sdist_name = f"{PROJECT_NAME}-{VERSION}.tar.gz"
    archive_root = f"{PROJECT_NAME}-{VERSION}"
    archive_path = sdist_root / sdist_name
    with tarfile.open(archive_path, "w:gz") as tf:
        for path in _iter_sdist_files():
            tf.add(path, arcname=f"{archive_root}/{path.relative_to(ROOT)}")
    return sdist_name
